marks.ioc:
// get the printParams object of the default printer
var pp = this.getPrintParams();
fv = pp.constants.flagValues;
pp.flags = pp.flags | fv.setPageSize | fv.suppressRotate;
pp.pageHandling = pp.constants.handling.none;

// print
this.print(pp);

